import assert from "node:assert/strict";
import { readFile, writeFile } from "node:fs/promises";

const manifest = JSON.parse(await readFile(new URL("../package.json", import.meta.url), "utf8"));
const destination = new URL("../src/contracts/version.ts", import.meta.url);

// These are authored contract identities, not derived from the package release.
// Changing semantics or a canonical profile requires explicit contract review.
const evaluatorVersion = "v0.0.5";
const schemaVersion = 4;
const generated = [
  "// Generated by scripts/version-metadata.mjs; do not edit directly.",
  `export const PACKAGE_VERSION = ${JSON.stringify(manifest.version)} as const;`,
  'export const EVALUATOR_ID = "assay" as const;',
  `export const EVALUATOR_VERSION = ${JSON.stringify(evaluatorVersion)} as const;`,
  `export const SCHEMA_VERSION = ${schemaVersion} as const;`,
  `export const DEFINITION_DOMAIN = ${JSON.stringify(`assay:definition:v${schemaVersion}\n`)} as const;`,
  `export const REFERENCE_DOMAIN = ${JSON.stringify(`assay:reference:v${schemaVersion}\n`)} as const;`,
  `export const EVIDENCE_DOMAIN = ${JSON.stringify(`assay:evidence:v${schemaVersion}\n`)} as const;`,
  "",
].join("\n");

assert.equal(manifest.name, "@0xbuff/assay");
assert.equal(manifest.engines.node, ">=24");
assert.equal(manifest.type, "module");

if (process.argv.length === 3 && process.argv[2] === "--write") {
  await writeFile(destination, generated);
} else {
  assert.equal(process.argv.length, 2, "Use no arguments to verify, or --write to generate");
  const actual = await readFile(destination, "utf8");
  assert.equal(
    actual.replaceAll("\r\n", "\n"),
    generated,
    "Version metadata is stale; run pnpm generate:version after authorized changes",
  );
  console.log("Package, evaluator and canonical profile metadata verified");
}
